import{_ as s,a0 as p,w as u,s as e,I as l,x as n,a1 as o,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"将自己作为承包商而定价的基础原则 | LCTT x X-CMD","titleTemplate":false,"description":"将自己作为承包商而定价的基础原则 | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"将自己作为承包商而定价的基础原则 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"将自己作为承包商而定价的基础原则 | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20210704 Pricing Yourself as a Contractor 101","title":"将自己作为承包商而定价的基础原则","tag":"202201","desc":""},"relativePath":"202201/20210704 Pricing Yourself as a Contractor 101.md","filePath":"[post].md"}'),m={name:"202201/20210704 Pricing Yourself as a Contractor 101.md"};function f(d,t,a,b,g,C){const r=p("Link");return u(),e("div",null,[t[30]||(t[30]=l("h1",{id:"将自己作为承包商而定价的基础原则",tabindex:"-1"},[n("将自己作为承包商而定价的基础原则 "),l("a",{class:"header-anchor",href:"#将自己作为承包商而定价的基础原则","aria-label":"Permalink to “将自己作为承包商而定价的基础原则”"},"​")],-1)),t[31]||(t[31]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202201/20/095355ib1k816i22fieoeh.jpg",alt:""})],-1)),t[32]||(t[32]=l("p",null,"我职业生涯的大部分时间都是自由职业者。有时候，我也会和一些想要辞掉全职工作去做一些承包或服务业务的人聊天。到目前为止，我们新手最常犯的错误就是为自己定价。",-1)),l("p",null,[t[1]||(t[1]=n("以 ",-1)),o(r,{href:"https://calebporzio.com/making-100k-as-an-employee-versus-being-self-employed"},{default:i(()=>[...t[0]||(t[0]=[n("这篇有用的博客文章为例，它分析了美国雇员与自由职业者的收入间的对比",-1)])]),_:1}),t[2]||(t[2]=n("。据估计，在美国，作为一名自由职业者，你需要获得 14 万美元的收入，才能获得相当于 10 万美元的雇员薪酬。我记得当我第一次创业时，我发现这样的计算非常有用。而，有些人看到结果会想：“哎呀，如果我是自由职业者，我得赚 1.4 倍的钱。我真的能做到吗？”",-1))]),t[33]||(t[33]=l("p",null,"不，不，不，这种想法是落后的。",-1)),t[34]||(t[34]=l("h3",{id:"如何给自己定价",tabindex:"-1"},[n("如何给自己定价 "),l("a",{class:"header-anchor",href:"#如何给自己定价","aria-label":"Permalink to “如何给自己定价”"},"​")],-1)),t[35]||(t[35]=l("p",null,"让我们举个例子。假设你是一名全职软件工程师，年收入 10 万美元，你正考虑转成承保。",-1)),t[36]||(t[36]=l("p",null,"当你是自由职业者时候，你必须像做企业一样思考，因为这就是你的谋生方式。所以，你必须把所有的成本加起来，并计算出如何收回这些成本。电子表格的口碑很差（有一些很好的理由），但它们实际上非常有用，尤其是对这些东西（以及作为企业主要进行的许多其他计算）。",-1)),t[37]||(t[37]=l("p",null,"第一个要加入统计的成本是那 10 万美元。如果这听起来很奇怪，那就是所谓的“机会成本”。你本可以继续工作以赚到 10 万美元；而没有赚到这 10 万美元，实际上是在规划业务时的一种成本。把这一费用和其他你实际使用的任何其它就业福利一起记下来。如果你的雇主提供工作日午餐，那就加上一年中每个工作日午餐的费用。如果你的雇主为员工提供健身软件的折扣，但你却没有使用该软件，那么不要将该福利作为机会成本。",-1)),t[38]||(t[38]=l("p",null,"其他费用取决于你在做什么和你住在哪里。员工医疗保险在澳大利亚不像在美国那么重要。另一方面，强制性养老金支付（类似于美国的 401(K) 计划）是一个大问题。我有自己的公司，我的主要非工资成本是保险、会计/档案、法律（合同审查等）、债务催收和各种在线服务成本。如果你在计算一些耐用的东西（比如一张桌子），把成本除以你预计使用该东西的年数。",-1)),l("p",null,[t[4]||(t[4]=n("总之，到目前为止，这基本上就是 Caleb 的博客文章中的内容，所以为了简单起见，我将假设同样的 10 万美元的名义工资和 14 万美元的等效业务成本。（当然，一切都要根据自己的情况进行调整。）现在你需要想办法收回这笔成本。澳大利亚一年大约有 255 个工作日，所以如果你能把它们全部外包出去，你每天要收取 550 美元（外加销售税）。在现实中，你不可能为一整年的工作计费。我采取了一种风险更高的方法，在我目前从事自营职业的过去 6 年里，我的平均回报率约为 60%-70%。",-1)),o(r,{href:"https://www.accenture.com/au-en/about/company/annual-report"},{default:i(()=>[...t[3]||(t[3]=[n("埃森哲的年度财务报告",-1)])]),_:1}),t[5]||(t[5]=n(" 说他们的承包商的“利用率”大约为 90%，我想这意味着他们付费了 90% 的总工作日的费用。让我们假设你的工作适度，75% 的工作日都有付账。这意味着你可以在 255 天的 75%（即 191 天） 里收回了 14 万美元的成本，每天开出 730 美元的账单（加上销售税）。",-1))]),t[39]||(t[39]=l("h3",{id:"误区",tabindex:"-1"},[n("误区 "),l("a",{class:"header-anchor",href:"#误区","aria-label":"Permalink to “误区”"},"​")],-1)),t[40]||(t[40]=l("p",null,"刚接触合同的人通常会对这样的数字做出反应，并会想，“见鬼？！这么高啊！”。这只是一个计算示例，但服务价格通常相当于你天真猜测的全职雇员工资的两倍或两倍以上。然而，这日薪是通过一个简单的计算得出的，那就是你需要收取多少钱才能获得相当于 10 万美元的工资。这是一回事。不这样想才是关键的错误。",-1)),t[41]||(t[41]=l("p",null,"新的承包商往往还不敢确定，他们要求那么多，听起来是不是很贪婪？如果你的客户有考虑采购你，他们也在做大致相同的计算。“我可以付给 Gentle Blog Reader 每天 730 美元，只要我愿意，我也可以花大约 14 万美元雇佣一个我甚至不是每天都真正需要的全职雇员。”从雇主的角度来看，10 万美元的薪水实际上也不是 10 万美元。把价格建立在名义基本工资的基础上是没有意义的。即使你是在销售 B2C 产品，你的潜在竞争对手也不会降价，至少不会持续降价。",-1)),t[42]||(t[42]=l("h3",{id:"为什么这很重要",tabindex:"-1"},[n("为什么这很重要 "),l("a",{class:"header-anchor",href:"#为什么这很重要","aria-label":"Permalink to “为什么这很重要”"},"​")],-1)),l("p",null,[t[7]||(t[7]=n("这个具体的例子是针对承包的，但这是商业经济学的一条基本规则：除非你正在尝试一些风险极高的高收入行为（我们知道 ",-1)),o(r,{href:"https://en.wikipedia.org/wiki/Pets.com"},{default:i(()=>[...t[6]||(t[6]=[n("Pets.com",-1)])]),_:1}),t[8]||(t[8]=n(" 的结果），否则你需要计算出你的成本，并设定足够高的价格来弥补这些成本。",-1))]),t[43]||(t[43]=l("p",null,"一些人仍然对他们需要设定的价格感到不安，他们认为降低价格是合理的。也许他们会这样想:“我是个很好的人，如果我每天只收 400 美元，我的客户会更高兴。”问题是你得不到同样的客户。那些愿意为雇员支付 10 万美元年薪的客户，不会为承包商支付 400 美元一天来做同样的工作。相反，在实践中，你可能会得到一些好客户，他们只是没有每天 730 美元的预算，但同时你也会得到一大堆非常糟糕的客户。想想看。如果一个陌生人以 50 美元的价格卖给你一枚看起来很精美的钻戒，你会付钱吗？还是宁愿以正常价格买另一枚戒指？",-1)),t[44]||(t[44]=l("p",null,"我要强调的是，我只是从 Caleb 的博客文章中提取了数据，而且一切都是相对的。用你自己的数字代替吧。在世界上大多数地区，每天 400 美元可能是一个令人难以置信的价格。然而，如果你是硅谷的一名高级金融科技开发人员，每天收费 400 美元只会让你成为吸引糟糕客户的磁铁。大多数优秀的人都会知道有些事情不对劲，他们会被吓跑。",-1)),l("p",null,[t[10]||(t[10]=n("我说的糟糕客户是什么意思？浏览一下 ",-1)),o(r,{href:"https://clientsfromhell.net/"},{default:i(()=>[...t[9]||(t[9]=[n("“来自地狱的客户”博客",-1)])]),_:1}),t[11]||(t[11]=n(" 吧。它包括很多基本的烦恼，比如客户永远不会得到满足，或者提出无理要求，或者浪费你的时间，一直到彻头彻尾的辱骂，或者让你按规格工作，然后辩称自己不应该付钱，因为“我不想要”。有些客户根本就不付钱。",-1))]),t[45]||(t[45]=l("p",null,"如果你不够重视你自己的产品，也不要因为你的客户不够重视你的产品而感到震惊。",-1)),t[46]||(t[46]=l("p",null,"不过，情况会变得更糟。好客户倾向于与其他好客户合作。如果你总是按时做到，你会和那些浪费你时间的人一起工作吗？如果你尊重他人，你会和那些不讲道理、辱骂他人的人一起工作吗？一般来说，你的好客户会把你介绍给其他好客户。糟糕的客户则恰恰相反，如果他们甚至会感激地把你推荐给任何人的话。因此，如果你的价格合适，你的生意会随着你的声誉而增长。如果你收费过低，你会发现自己陷入了一个恶性循环，你不仅会赔钱，而且会发现越来越难获得适当的报酬。",-1)),t[47]||(t[47]=l("p",null,"这些都只是平均水平，如果你幸运的话，低收费也能吸引到好客户，如果你不幸的话，价格合理也仍然会得到坏客户。然而，如果你的收入已经很低了，那么每一个坏客户都会对你造成伤害。希望超越平均水平不是一个好计划。",-1)),t[48]||(t[48]=l("h3",{id:"但没人付那么多钱",tabindex:"-1"},[n("“但没人付那么多钱！” "),l("a",{class:"header-anchor",href:"#但没人付那么多钱","aria-label":"Permalink to ““但没人付那么多钱！””"},"​")],-1)),t[49]||(t[49]=l("p",null,"假设你是一名经验丰富的全职工程师，你决定尝试独立工作。你可能会发现，你的计算比率似乎比你在自由职业网站上看到的要高。这是因为在自由职业网站上建立声誉很难。自由职业者网站对于那些主要想要低价的临时买家来说是最有用的。",-1)),t[50]||(t[50]=l("p",null,"我想，很多聪明的工程师都认为，职业社交是很难的，而且需要非常外向的性格，所以他们不得不依靠自由职业网站来工作。坏消息是，你需要建立良好的声誉才能拿到高薪。好消息是，只要他们拥有所需的技能，大多数人都可以做到。社交并不是去参加所谓的“社交活动”（实际上，这些活动对社交来说都很糟糕）。建立关系网的技巧可以写一篇全新的博客文章，但关键是在他们的日常生活中找到好客户，并做一些让他们不断回头的事情，甚至可能让你找到其他好客户。",-1)),l("p",null,[t[13]||(t[13]=n("在任何情况下，不要让自由职业网站或其他任何东西把你的价格定在你可以从全职工资中拿到的等价物以下。事实上，",-1)),o(r,{href:"https://theartofmachinery.com/2018/10/07/payrise_by_switching_jobs.html"},{default:i(()=>[...t[12]||(t[12]=[n("你甚至可能比你现在的工资还高",-1)])]),_:1}),t[14]||(t[14]=n("，这就是为什么这是 “定价基础原则”。收费过低会扼杀你的自主创业生涯。",-1))]),t[51]||(t[51]=l("hr",null,null,-1)),l("p",null,[t[16]||(t[16]=n("via: ",-1)),o(r,{href:"https://theartofmachinery.com/2021/07/04/pricing_as_contractor_101.html"},{default:i(()=>[...t[15]||(t[15]=[n("https://theartofmachinery.com/2021/07/04/pricing_as_contractor_101.html",-1)])]),_:1})]),l("p",null,[t[21]||(t[21]=n("作者：",-1)),o(r,{href:"https://theartofmachinery.com"},{default:i(()=>[...t[17]||(t[17]=[n("Simon Arneaud",-1)])]),_:1}),t[22]||(t[22]=n(" 选题：",-1)),o(r,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[18]||(t[18]=[n("lujun9972",-1)])]),_:1}),t[23]||(t[23]=n(" 译者：",-1)),o(r,{href:"https://github.com/CN-QUAN"},{default:i(()=>[...t[19]||(t[19]=[n("CN-QUAN",-1)])]),_:1}),t[24]||(t[24]=n(" 校对：",-1)),o(r,{href:"https://github.com/wxy"},{default:i(()=>[...t[20]||(t[20]=[n("wxy",-1)])]),_:1})]),l("p",null,[t[27]||(t[27]=n("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[25]||(t[25]=[n("LCTT",-1)])]),_:1}),t[28]||(t[28]=n(" 原创编译，",-1)),o(r,{href:"https://linux.cn/"},{default:i(()=>[...t[26]||(t[26]=[n("Linux中国",-1)])]),_:1}),t[29]||(t[29]=n(" 荣誉推出",-1))])])}const P=s(m,[["render",f]]);export{k as __pageData,P as default};
